import React,{useEffect,useMemo,useRef,useState} from 'react';
import {ReactFlow,Background,Controls,Handle,Position,useNodesInitialized,useReactFlow} from '@xyflow/react';
import {createHourlyModelComponents,assertHourlyModelComponents,compileHourlyComponentGraph,HOURLY_COMPONENT_REGISTRY as registry,HOURLY_FEATURE_LABELS} from '../domain/hourly-model-components.mjs';
import {hourlyComponentTitle,hourlyTreeView} from './hourly-model-view.mjs';
import {StrategyPartCard,StrategyGlyph,StrategyToolButton} from './strategy-part-card.jsx';
const portName=p=>({parent:'입력',left:'이하',right:'초과',bars:'확정 시간봉',value:'계산값',features:'8개 특징',values:'경로 예측',forecast:'예상 수익률',candles:'과거 시세',rows:'학습 표본',forest:'학습된 나무',model:'모델 버전'}[p]??HOURLY_FEATURE_LABELS[p]??p);
const typeName=t=>({OHLCV:'시세',NUMBER:'숫자',FEATURE_VECTOR:'특징 묶음',PATH_VALUES:'경로 예측',PATH_RETURN:'예상 수익률',CANDLES:'과거 시세',TRAINING_ROWS:'학습 표본',LOG_TRAINING_ROWS:'로그 목표 표본',TRAINED_FOREST:'학습된 나무',MODEL:'모델 버전'}[t]??t);
const icons={BARS:'candles',CANDLES:'database',FEATURE:'formula',PACK:'merge',TREE:'branch',MEAN:'formula',RETURN:'number',SAMPLES:'database',LOG_TARGET:'formula',FIT:'model',MODEL:'model',SPLIT:'compare',LEAF:'number'};
const title=n=>hourlyComponentTitle(n)??registry[n.type]?.title??(n.type==='SPLIT'?'조건 '+(n.index+1):'예측 결과 '+(n.index+1));
const pct=n=>Number.isFinite(n)?(n*100).toLocaleString('ko-KR',{maximumFractionDigits:3})+'%':'—';
const rowsOf=(n,model)=>n.type==='FEATURE'?[['계산',HOURLY_FEATURE_LABELS[n.config.feature]],['비교 기간',n.config.period+'봉']]:n.type==='TREE'?[['조건 수',(model.trees[n.config.treeIndex]?.filter(v=>!v.values).length??0)+'개'],['출력',model.horizonBars+'봉 수익·하방']]:n.type==='SAMPLES'?[['학습 구간','최근 '+n.config.trainingDays+'일'],['입력 → 정답','30봉 → 다음 '+model.horizonBars+'봉']]:n.type==='FIT'?[['학습 나무',n.config.trees+'개'],['최대 깊이',n.config.maxDepth],['잎 최소 표본',n.config.minLeaf]]:n.type==='SPLIT'?[['비교 지표',HOURLY_FEATURE_LABELS[n.feature]],['분기 기준','≤ '+n.threshold.toPrecision(6)]]:n.type==='LEAF'?[['예상 수익',pct(n.values[0])],['예상 하방',pct(n.values[1])],['학습 표본',n.samples+'개']]:[];
function ComponentNode({data,selected}){
 const n=data.node,spec=registry[n.type],inputs=spec?.inputs??(n.index===0?[]:[{id:'parent'}]),outputs=spec?.outputs??(n.type==='SPLIT'?[{id:'left'},{id:'right'}]:[]);
 return <StrategyPartCard node={n} cohortId={spec?.cohort??(n.type==='SPLIT'?'CONDITION':'COMPUTE')} iconId={icons[n.type]} title={title(n)} kindLabel={n.type==='TREE'?'학습된 조건':'내부 부품'} selected={selected} subtitle={n.type==='LOG_TARGET'?'log(1 + 실제 수익률)':n.type==='MEAN'?'연결된 예측을 같은 비중으로 평균':n.type==='RETURN'?'로그 예측 → 수익률':n.type==='PACK'?'연결 순서가 아닌 특징 이름으로 묶음':n.type==='BARS'?'판단 시점 이전 확정 30봉':null}>
  <dl className="strategy-node-summary">{rowsOf(n,data.model).map(([label,value])=><div key={label}><dt>{label}</dt><dd title={String(value)}>{value}</dd></div>)}</dl>
  {n.type==='TREE'&&<button type="button" className="button small nodrag nopan" onPointerDown={e=>{e.preventDefault();e.stopPropagation();}} onMouseDown={e=>e.stopPropagation()} disabled={!Number.isSafeInteger(n.config.treeIndex)||!data.model.trees[n.config.treeIndex]} onClick={e=>{e.stopPropagation();data.onTree(n.config.treeIndex);}}>조건·예측 펼치기</button>}
  <div className="strategy-data-ports">{Array.from({length:Math.max(inputs.length,outputs.length)},(_,i)=><div className="strategy-data-port-row" key={i}>{inputs[i]?<span className="strategy-data-port-label"><Handle id={inputs[i].id} type="target" position={Position.Left} aria-label={title(n)+' 입력 '+portName(inputs[i].id)}/>{portName(inputs[i].id)}</span>:<span/>}{outputs[i]?<span className="strategy-data-port-label"><Handle id={outputs[i].id} type="source" position={Position.Right} aria-label={title(n)+' 출력 '+portName(outputs[i].id)}/>{portName(outputs[i].id)}</span>:<span/>}</div>)}</div>
 </StrategyPartCard>;
}
const nodeTypes={component:ComponentNode};
function placement(nodes){const counts={};return nodes.map(n=>{const column=({BARS:0,FEATURE:1,PACK:2,TREE:3,MEAN:4,RETURN:5,CANDLES:0,SAMPLES:1,LOG_TARGET:2,FIT:3,MODEL:4})[n.type],row=counts[column]??0;counts[column]=row+1;return {id:n.id,type:'component',position:{x:column*320,y:row*340},data:{node:n}};});}
function FitModelView({viewKey,selected}){const ready=useNodesInitialized(),flow=useReactFlow(),fitted=useRef(null);useEffect(()=>{if(!ready||fitted.current===viewKey)return;fitted.current=viewKey;flow.fitView({nodes:selected?[{id:selected}]:undefined,padding:.3,minZoom:.85,maxZoom:1});},[ready,viewKey,selected,flow]);return null;}
export function HourlyModelComponentEditor({name='학습 모델',model,components,readOnly=false,onDone,onClose}){
 const [draft,setDraft]=useState(()=>structuredClone(components??createHourlyModelComponents(model))),[phase,setPhase]=useState('inference'),[selected,setSelected]=useState('bars'),[message,setMessage]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[flow,setFlow]=useState(null),[treeIndex,setTreeIndex]=useState(null),[propertiesOpen,setPropertiesOpen]=useState(false),[measurements,setMeasurements]=useState({});
 const history=useRef([]),graph=draft[phase],current=graph.nodes.find(n=>n.id===selected),tree=useMemo(()=>treeIndex===null?null:hourlyTreeView(model,treeIndex),[model,treeIndex]),rendered=useMemo(()=>tree?tree.nodes.map(n=>({id:n.id,type:'component',position:{x:n.depth*320,y:n.row*260},data:{node:n}})):placement(graph.nodes),[graph,tree]);
 let problem='';try{assertHourlyModelComponents(draft,model);}catch(e){problem=e.message;}
 const select=id=>{setSelected(id);setPropertiesOpen(true);},openTree=index=>{setTreeIndex(index);setPropertiesOpen(false);setMeasurements({});};
 function change(next){if(readOnly)return;history.current.push(draft);setDraft(next);setMessage('');}
 function patch(config){change({...draft,[phase]:{...graph,nodes:graph.nodes.map(n=>n.id===current.id?{...n,config}:n)}});}
 function connect(source,target,sourceHandle,targetHandle){if(readOnly||tree)return;const a=graph.nodes.find(n=>n.id===source),b=graph.nodes.find(n=>n.id===target),out=registry[a?.type]?.outputs.find(p=>p.id===sourceHandle),input=registry[b?.type]?.inputs.find(p=>p.id===targetHandle);if(!out||!input||out.type!==input.type||source===target){setMessage('같은 자료 타입의 서로 다른 부품을 연결하세요.');return;}
  const edges=graph.edges.filter(e=>!(e.to.nodeId===target&&e.to.port===targetHandle&&!input.many));if(edges.some(e=>e.from.nodeId===source&&e.from.port===sourceHandle&&e.to.nodeId===target&&e.to.port===targetHandle)){setMessage('이미 연결되어 있습니다.');return;}
  const next={...graph,edges:[...edges,{id:'link-'+crypto.randomUUID(),from:{nodeId:source,port:sourceHandle},to:{nodeId:target,port:targetHandle}}]};try{compileHourlyComponentGraph(next,phase,model);}catch(e){if(!['MODEL_COMPONENT_PORT','MODEL_COMPONENT_UNUSED'].includes(e.code)){setMessage(e.message);return;}}change({...draft,[phase]:next});
 }
 function add(type){const id='part-'+crypto.randomUUID(),config=type==='FEATURE'?{feature:'return_1bar',period:1}:type==='TREE'?{treeIndex:0}:{};change({...draft,[phase]:{...graph,nodes:[...graph.nodes,{id,type,config}]}});select(id);}
 const options=direction=>graph.nodes.flatMap(n=>registry[n.type][direction].map(p=><option key={n.id+'|'+p.id} value={n.id+'|'+p.id}>{title(n)} · {portName(p.id)} · {typeName(p.type)}</option>));
 const numeric=(key,label,min,max,disabled=false)=><label className="field" key={key}>{label}<input type="number" aria-label={label} min={min} max={max} step="1" value={current.config[key]} disabled={readOnly||disabled} onChange={e=>patch({...current.config,[key]:e.target.value===''?'':Number(e.target.value)})}/></label>;
 const path=id=>{setPhase(id);setTreeIndex(null);setSelected(id==='inference'?'bars':'candles');setPropertiesOpen(false);setMeasurements({});setFrom('');setTo('');setMessage('');};
 return <section className={'model-components-workspace'+(tree?' model-tree-view':'')+(propertiesOpen?' model-properties-open':'')} aria-label="학습모델 내부 편집">
  <header className="strategy-editor-toolbar"><div className="strategy-editor-context"><button type="button" className="button small" onClick={onClose}>전략으로</button><strong title={name}>{name} / 내부 구성</strong></div><div className="strategy-editor-tools"><StrategyToolButton icon="fit" label="내부 전체 보기" onClick={()=>flow?.fitView({padding:.2,maxZoom:1})}/><StrategyToolButton icon="undo" label="내부 되돌리기" disabled={readOnly||!history.current.length} onClick={()=>{setDraft(history.current.pop());setMessage('');}}/><button type="button" className="button primary" disabled={Boolean(problem)} onClick={()=>onDone(draft)}>{readOnly?'전략으로 돌아가기':'변경 적용 · 전략으로'}</button></div></header>
  <nav className="model-path-tabs" aria-label="모델 내부 경로">{[['inference','예측 경로'],['training','학습 경로']].map(([id,label])=><button key={id} className="button small" aria-pressed={phase===id&&!tree} onClick={()=>path(id)}>{label}</button>)}{tree&&<><span>/ 조건나무 {treeIndex+1}</span><button className="button small" onClick={()=>{setTreeIndex(null);setMeasurements({});}}>예측 경로로</button></>}<span className="model-path-description">{tree?'실제 저장된 분기 기준 · 학습 결과':phase==='training'?'과거 시세 → 30봉 입력·'+model.horizonBars+'봉 정답 → 로그 목표 → 조건나무 학습 → 버전 생성':'확정 30봉 → 8개 특징 → 조건나무 → 예측 평균 → 수익률'}</span></nav>
  {tree?<label className="model-mobile-select">조건·예측<select aria-label="펼친 나무의 조건·예측" defaultValue="tree-node-0" onChange={e=>flow?.fitView({nodes:[{id:e.target.value}],padding:.4,minZoom:.85,maxZoom:1})}>{tree.nodes.map(n=><option key={n.id} value={n.id}>{n.type==='SPLIT'?HOURLY_FEATURE_LABELS[n.feature]+' ≤ '+n.threshold.toPrecision(4):'예측 '+pct(n.values[0])}</option>)}</select></label>:<label className="model-mobile-select">부품<select aria-label="모델 내부 부품" value={selected??''} onChange={e=>{select(e.target.value);flow?.fitView({nodes:[{id:e.target.value}],padding:.4,minZoom:.85,maxZoom:1});}}>{graph.nodes.map(n=><option key={n.id} value={n.id}>{title(n)}</option>)}</select></label>}<div className="model-components-body"><aside className="model-components-outline" aria-label="모델 구성 목록">{tree?<><h3>조건나무 {treeIndex+1}</h3><p>모델에 저장된 조건과 예측 결과입니다.</p>{tree.nodes.map(n=><button className="button small" key={n.id} onClick={()=>flow?.fitView({nodes:[{id:n.id}],padding:.5,minZoom:.85,maxZoom:1})}>{n.type==='SPLIT'?HOURLY_FEATURE_LABELS[n.feature]+' ≤ '+n.threshold.toPrecision(4):'예측 '+pct(n.values[0])}</button>)}</>:<>{graph.nodes.map(n=><button type="button" className="strategy-outline-node" key={n.id} aria-pressed={selected===n.id} onClick={()=>{select(n.id);flow?.fitView({nodes:[{id:n.id}],padding:.4,minZoom:.85,maxZoom:1});}}><StrategyGlyph id={icons[n.type]}/><span>{title(n)}</span></button>)}{phase==='inference'&&!readOnly&&<details><summary>부품 추가</summary>{['FEATURE','TREE','MEAN'].map(type=><button key={type} type="button" className="button small" onClick={()=>add(type)}>{registry[type].title} 추가</button>)}</details>}</>}</aside>
   <section className="model-components-canvas" aria-label="모델 내부 노드 캔버스"><ReactFlow key={phase+'-'+treeIndex} onInit={setFlow} nodes={rendered.map(n=>({...n,width:272,measured:measurements[n.id],selected:n.id===selected&&!tree,data:{...n.data,model,onTree:openTree}}))} edges={tree?tree.edges.map(e=>({...e,type:'smoothstep',sourceHandle:e.label==='이하'?'left':'right',targetHandle:'parent'})):graph.edges.map(e=>({id:e.id,source:e.from.nodeId,target:e.to.nodeId,sourceHandle:e.from.port,targetHandle:e.to.port,type:'smoothstep'}))} nodeTypes={nodeTypes} minZoom={.1} maxZoom={1.5} nodesDraggable={false} nodesConnectable={!readOnly&&!tree} edgesFocusable={!tree} onNodesChange={changes=>{const sizes=changes.filter(c=>c.type==='dimensions'&&c.dimensions);if(sizes.length)setMeasurements(previous=>({...previous,...Object.fromEntries(sizes.map(c=>[c.id,c.dimensions]))}));}} onNodeClick={(_,n)=>{if(!tree)select(n.id);}} onConnect={c=>connect(c.source,c.target,c.sourceHandle,c.targetHandle)} onEdgesDelete={edges=>!readOnly&&!tree&&change({...draft,[phase]:{...graph,edges:graph.edges.filter(e=>!edges.some(d=>d.id===e.id))}})}><FitModelView viewKey={phase+'-'+treeIndex} selected={tree?'tree-node-0':selected}/><Background/><Controls showInteractive={false}/></ReactFlow></section>
   {!tree&&<aside className="model-components-properties" aria-label="내부 부품 설정"><header><strong>{current?title(current):'부품 선택'}</strong><button type="button" className="button small" onClick={()=>setPropertiesOpen(false)} aria-label="내부 그래프로">그래프로</button></header>{current&&<>
    {current.type==='FEATURE'&&<><label className="field">계산 지표<select aria-label="계산 지표" value={current.config.feature} disabled={readOnly} onChange={e=>patch({...current.config,feature:e.target.value,period:Math.min(current.config.period,29)})}>{Object.entries(HOURLY_FEATURE_LABELS).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>{numeric('period','비교 기간 · 봉',1,['sma30_distance','range24','high24_distance'].includes(current.config.feature)?30:29)}<p>이 연결과 계산 기간은 예측과 다음 재학습의 입력에 함께 사용됩니다.</p></>}
    {current.type==='TREE'&&<>{numeric('treeIndex','학습 나무 번호 · 0부터',0,model.trees.length-1)}<button className="button primary" disabled={!Number.isSafeInteger(current.config.treeIndex)||!model.trees[current.config.treeIndex]} onClick={()=>openTree(current.config.treeIndex)}>조건·예측 펼치기</button><p>조건값과 잎의 예측은 학습 결과입니다. 연결할 나무는 이 부품에서 선택합니다.</p></>}
    {current.type==='SAMPLES'&&<>{numeric('trainingDays','최근 학습 일수',1,7)}<p>확정 30봉의 특징과 그 이후 {model.horizonBars}봉의 실제 결과를 짝짓습니다. 학습 종료 시점 이후 정답은 제외합니다.</p></>}
    {current.type==='FIT'&&<>{numeric('trees','학습 나무 수',1,32,true)}{numeric('maxDepth','나무 최대 깊이',1,5)}{numeric('minLeaf','잎의 최소 표본 수',1,100000)}{numeric('seed','학습 재현 시드',0,4294967295)}<p>현재 버전의 나무 수를 유지합니다. 이 설정은 자동 학습이 켜진 마인드의 다음 재학습에 사용됩니다.</p></>}
    {current.type==='LOG_TARGET'&&<p>각 실제 수익률을 log(1+r)로 바꾸어 학습합니다. 반복 투자에서 큰 손실이 미치는 영향을 함께 반영합니다.</p>}
    {current.type==='MEAN'&&<p>연결된 나무의 예측을 같은 비중으로 평균합니다. 연결한 나무들이 실제 계산에 사용됩니다.</p>}
    {current.type==='RETURN'&&<p>{model.targetTransform==='LOG1P'?'로그 평균에 expm1을 적용해 수익률로 되돌립니다.':'현재 모델의 수익률을 그대로 전달합니다.'}</p>}
    {current.type==='PACK'&&<p>8개 특징 입력을 모델의 학습 순서로 묶습니다. 각 포트의 연결을 바꾸어 실제 계산을 조립합니다.</p>}
    {current.type==='BARS'&&<p>상위 전략의 시세 입력을 받습니다. 판단 시점 이전에 확정된 연속 30개 {model.timeframe} 봉을 사용합니다.</p>}
    {current.type==='CANDLES'&&<p>자동 학습이 보존한 과거 시세입니다. 자료가 수신된 시점과 확정 봉 시각을 확인해 학습에 사용합니다.</p>}
    {current.type==='MODEL'&&<p>학습 표본·시점·가중치가 결속된 모델 버전을 만듭니다. 버전의 표본 수는 {model.training.sampleCount.toLocaleString()}개입니다.</p>}
    {!readOnly&&!['BARS','RETURN','CANDLES','MODEL'].includes(current.type)&&<button type="button" className="button small strategy-delete" onClick={()=>{change({...draft,[phase]:{...graph,nodes:graph.nodes.filter(n=>n.id!==current.id),edges:graph.edges.filter(e=>e.from.nodeId!==current.id&&e.to.nodeId!==current.id)}});setSelected(null);}}>부품 삭제</button>}
   </>}
   <details><summary>목록으로 연결 편집</summary><label className="field">출력<select aria-label="내부 연결 출력" value={from} onChange={e=>setFrom(e.target.value)}><option value="">출력 선택</option>{options('outputs')}</select></label><label className="field">입력<select aria-label="내부 연결 입력" value={to} onChange={e=>setTo(e.target.value)}><option value="">입력 선택</option>{options('inputs')}</select></label><button type="button" className="button" disabled={readOnly||!from||!to} onClick={()=>{const [a,ap]=from.split('|'),[b,bp]=to.split('|');connect(a,b,ap,bp);}}>연결하기</button><label className="field">기존 연결<select aria-label="삭제할 내부 연결" disabled={readOnly} value="" onChange={e=>{if(e.target.value)change({...draft,[phase]:{...graph,edges:graph.edges.filter(v=>v.id!==e.target.value)}});}}><option value="">삭제할 연결 선택</option>{graph.edges.map(e=><option key={e.id} value={e.id}>{title(graph.nodes.find(n=>n.id===e.from.nodeId))} → {title(graph.nodes.find(n=>n.id===e.to.nodeId))} · {portName(e.to.port)}</option>)}</select></label></details>
   </aside>}
  </div><footer className="model-components-footer" role={message||problem?'alert':'status'}>{message||problem||'입력·연결 확인 완료 · 변경 적용 후 상위 전략과 함께 저장됩니다.'}</footer>
 </section>;
}
